    static inline QBasicAtomicInt destroyed = Q_BASIC_ATOMIC_INITIALIZER(0);

    ClearingPayload() = default;
    ClearingPayload(ClearingPayload &&other) noexcept
        : armed(std::exchange(other.armed, false)) {}
    ClearingPayload &operator=(ClearingPayload &&) = delete;
    ~ClearingPayload()
    {
        if (!armed)
            return;
        destroyed.ref();
        self->clearLocalData();  // re-entrant: already detached, must be a no-op
        other->clearLocalData(); // destroys other's payload, if any
    }

    bool armed = true;
};

} // unnamed namespace

void tst_QThreadStorage::clearInDestructor()
{
    QThreadStorage<ClearingPayload> first;
    QThreadStorage<ClearingPayload> second;
    ClearingPayload::self = &first;
    ClearingPayload::other = &second;
    auto cleanup = qScopeGuard([] {
        ClearingPayload::self = nullptr;
        ClearingPayload::other = nullptr;
    });

    auto run = [&] {
        ClearingPayload::destroyed.storeRelaxed(0);
        first.localData();
        second.localData();
        first.clearLocalData();
    };

    // explicit clearLocalData():
    std::thread t1([&] {
        run();
        QVERIFY(!first.hasLocalData());
        QVERIFY(!second.hasLocalData());
        QCOMPARE(ClearingPayload::destroyed.loadRelaxed(), 2);
    });
    t1.join();

    // thread exit, with the first payload still set:
    std::thread t2([&] {
        ClearingPayload::destroyed.storeRelaxed(0);
        first.localData();
        second.localData();
    });
    t2.join();
    QCOMPARE(ClearingPayload::destroyed.loadRelaxed(), 2);
}

